n WORKTREE fell back to MAIN_WT we can't attribute dirtiness to\\n# this branch, so we skip (the loop always seeds a distinct worktree).\\nif [ \\\"$WORKTREE\\\" != \\\"$MAIN_WT\\\" ]; then\\n  DIRTY=$(git -C \\\"$WORKTREE\\\" status --porcelain 2\\u003e/dev/null || echo \\\"\\\")\\n  if [ -n \\\"$DIRTY\\\" ]; then\\n    emit --arg wt \\\"$WORKTREE\\\" --arg files \\\"$DIRTY\\\" '{outcome:\\\"uncommitted\\\",integrated_sha:\\\"\\\",last_op_ok:false,last_error:(\\\"refusing to integrate: the maker worktree \\\"+$wt+\\\" has uncommitted work — it was never committed, so integrating would land an empty or partial shell. Commit it on the branch first:\\\\n\\\"+$files)}'\\n  fi\\nfi\\n# Rebase the branch onto CURRENT integration HEAD, IN ITS OWN\\n# worktree. merge-base is computed against the live INTEGRATION ref\\n# (re-read here, so a concurrent moved-main is absorbed).\\nMB=$(git -C \\\"$WORKTREE\\\" merge-base \\\"$BRANCH\\\" \\\"$INTEGRATION\\\" 2\\u003e/dev/null || echo \\\"\\\")\\nREBASE_EXIT=0\\nREBASE_OUT=$(git -C \\\"$WORKTREE\\\" rebase --onto \\\"$BASE_SHA\\\" \\\"$MB\\\" \\\"$BRANCH\\\" 2\\u003e\\u00261) || REBASE_EXIT=$?\\nif [ \\\"$REBASE_EXIT\\\" -ne 0 ]; then\\n  git -C \\\"$WORKTREE\\\" rebase --abort 2\\u003e/dev/null || true\\n  emit --arg out \\\"$REBASE_OUT\\\" '{outcome:\\\"conflict\\\",integrated_sha:\\\"\\\",last_op_ok:false,last_error:$out}'\\nfi\\n# Merge the rebased branch into INTEGRATION in MAIN_WT (merge does\\n# NOT check out the source branch, so no worktree-lock conflict).\\nPRE_MERGE_SHA=$(git -C \\\"$MAIN_WT\\\" rev-parse \\\"$INTEGRATION\\\" 2\\u003e/dev/null || echo \\\"\\\")\\n# Capture the checkout exit (#checkout): a failed checkout emits a\\n# clear error rather than tripping the trap's generic message.\\nCO_EXIT=0\\nCO_OUT=$(git -C \\\"$MAIN_WT\\\" checkout \\\"$INTEGRATION\\\" 2\\u003e\\u00261) || CO_EXIT=$?\\nif [ \\\"$CO_EXIT\\\" -ne 0 ]; then\\n  emit --arg out \\\"$CO_OUT\\\" --arg int \\\"$INTEGRATION\\\" '{outcome:\\\"er